fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let cs: i32 = w / 16;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 0);
        host::display::state_set(2, 2);
        host::display::state_set(3, 3);
        host::display::state_set(4, 1);
        host::display::state_set(5, 0);
        host::display::state_set(6, 0);
        host::display::state_set(20, 3 * 16 + 8);
        host::display::state_set(21, 4 * 16 + 8);
        host::display::state_set(22, 5 * 16 + 8);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(7) == 0;
    host::display::state_set(7, down);
    let phase: i32 = host::display::state_get(6);
    if phase == 1 {
        host::display::clear(0x180404);
        host::display::draw_string(130, 190, "GAME OVER", 0xff4040, 4);
        host::display::draw_string(160, 260, "ATE", 0x808080, 2);
        host::display::draw_number(230, 260, host::display::state_get(5), 0xffffff, 2);
        host::display::draw_string(140, 320, "TAP TO RESTART", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut dir: i32 = host::display::state_get(1);
        if tap {
            if host::display::pointer_x() < w / 2 {
                dir = (dir + 3) % 4;
            } else {
                dir = (dir + 1) % 4;
            }
            host::display::state_set(1, dir);
        }
        let mut hp: i32 = host::display::state_get(2);
        let mut len: i32 = host::display::state_get(3);
        if t % 6 == 0 {
            let head: i32 = host::display::state_get(20 + hp);
            let mut hx: i32 = head / 16;
            let mut hy: i32 = head % 16;
            if dir == 0 { hx = hx + 1; }
            if dir == 1 { hy = hy + 1; }
            if dir == 2 { hx = hx - 1; }
            if dir == 3 { hy = hy - 1; }
            if hx < 0 || hx > 15 || hy < 0 || hy > 15 {
                host::display::state_set(6, 1);
            } else {
                let np: i32 = hx * 16 + hy;
                let mut s: i32 = 0;
                let mut dead: i32 = 0;
                while s < len - 1 {
                    let slot: i32 = 20 + (((hp - s) % 40 + 40) % 40);
                    if host::display::state_get(slot) == np { dead = 1; }
                    s = s + 1;
                }
                if dead == 1 {
                    host::display::state_set(6, 1);
                } else {
                    hp = (hp + 1) % 40;
                    host::display::state_set(20 + hp, np);
                    host::display::state_set(2, hp);
                    let fr: i32 = host::display::state_get(4);
                    let f: i32 = hash(fr);
                    if hx == f % 16 && hy == (f / 16) % 16 {
                        host::display::state_set(4, fr + 1);
                        host::display::state_set(5, host::display::state_get(5) + 1);
                        if len < 39 { len = len + 1; }
                        host::display::state_set(3, len);
                    }
                }
            }
        }
        host::display::clear(0x001008);
        let f2: i32 = hash(host::display::state_get(4));
        host::display::fill_rect((f2 % 16) * cs + 4, ((f2 / 16) % 16) * cs + 4, cs - 8, cs - 8, 0xff3344);
        hp = host::display::state_get(2);
        len = host::display::state_get(3);
        let mut d: i32 = 0;
        while d < len {
            let slot2: i32 = 20 + (((hp - d) % 40 + 40) % 40);
            let p: i32 = host::display::state_get(slot2);
            let mut col: i32 = 0x00cc66;
            if d == 0 { col = 0x88ffbb; }
            host::display::fill_rect((p / 16) * cs + 2, (p % 16) * cs + 2, cs - 4, cs - 4, col);
            d = d + 1;
        }
        host::display::draw_number(8, 4, host::display::state_get(5), 0xffffff, 2);
    }
    host::display::present();
}
